using System;
using System.Data;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;

namespace InformationWeb.Controls.Graduation
{
    /// <summary>
    /// Điền dữ liệu chi tiết văn bằng tốt nghiệp lên PDF mẫu (phôi in).
    /// Tọa độ lấy từ Graduation_BangTotNghiep_SC2_1.repx (DevExpress, đơn vị 1/100 inch).
    /// PDF mẫu: ~/Template/MauPDF/Graduation_BangTotNghiep_SC2_1.pdf
    /// (Xuất 1 lần từ file .repx bằng DevExpress Report Designer, giữ nguyên khổ 800x780).
    /// </summary>
    public static class GraduationBangTotNghiepPdfFiller
    {
        public const string PDF_TEMPLATE_FILE = "Graduation_BangTotNghiep_SC2_1.pdf";

        private const float PAGE_WIDTH_DX = 800F;
        private const float PAGE_HEIGHT_DX = 780F;

        private delegate string GetFieldValueHandler(DataRow drw);

        private sealed class PdfTextField
        {
            public string AcroFieldName;
            public float X;
            public float Y;
            public float Width;
            public float Height;
            public float FontSize;
            public bool Bold;
            public GetFieldValueHandler GetValue;
        }

        private static readonly PdfTextField[] DetailFields = new PdfTextField[]
        {
            new PdfTextField { AcroFieldName = "StudentFullName", X = 176.8336F, Y = 295.5416F, Width = 549.4995F, Height = 25F, FontSize = 14F, Bold = true, GetValue = GetStudentFullName },
            new PdfTextField { AcroFieldName = "BirthDateText", X = 176.8336F, Y = 337.2083F, Width = 549.4996F, Height = 25F, FontSize = 14F, Bold = false, GetValue = GetBirthDateText },
            new PdfTextField { AcroFieldName = "SpecialBranchName", X = 288.9999F, Y = 377.6669F, Width = 437.3332F, Height = 24.04169F, FontSize = 14F, Bold = false, GetValue = GetSpecialBranchName },
            new PdfTextField { AcroFieldName = "StartAt_Day", X = 127.0834F, Y = 419.25F, Width = 57.04161F, Height = 25F, FontSize = 14F, Bold = false, GetValue = GetStartAtDay },
            new PdfTextField { AcroFieldName = "StartAt_Month", X = 233.0833F, Y = 419.25F, Width = 47.66661F, Height = 25F, FontSize = 14F, Bold = false, GetValue = GetStartAtMonth },
            new PdfTextField { AcroFieldName = "StartAt_Year", X = 316.1666F, Y = 419.3334F, Width = 62.24994F, Height = 25F, FontSize = 14F, Bold = false, GetValue = GetStartAtYear },
            new PdfTextField { AcroFieldName = "FinishAt_Day", X = 462.6669F, Y = 419.0833F, Width = 46.62491F, Height = 25F, FontSize = 14F, Bold = false, GetValue = GetFinishAtDay },
            new PdfTextField { AcroFieldName = "FinishAt_Month", X = 559.2917F, Y = 419.3334F, Width = 41.4166F, Height = 25F, FontSize = 14F, Bold = false, GetValue = GetFinishAtMonth },
            new PdfTextField { AcroFieldName = "FinishAt_Year", X = 646.5418F, Y = 419.0833F, Width = 79.79126F, Height = 25F, FontSize = 14F, Bold = false, GetValue = GetFinishAtYear },
            new PdfTextField { AcroFieldName = "GraduationLevel", X = 175.5417F, Y = 461.9999F, Width = 550.7913F, Height = 25F, FontSize = 14F, Bold = false, GetValue = GetGraduationLevel },
            new PdfTextField { AcroFieldName = "CerIssued", X = 490.7918F, Y = 498.5835F, Width = 235.5413F, Height = 25.00003F, FontSize = 14F, Bold = false, GetValue = GetCerIssuedSpaced },
            new PdfTextField { AcroFieldName = "CerNo", X = 127.0832F, Y = 610.375F, Width = 599.2498F, Height = 25.08325F, FontSize = 14F, Bold = false, GetValue = GetCerNo },
            new PdfTextField { AcroFieldName = "SavedCerNo", X = 233.0831F, Y = 635.4582F, Width = 493.2499F, Height = 24.04163F, FontSize = 14F, Bold = false, GetValue = GetSavedCerNo }
        };

        public static void FillDetailPdf(string templatePath, string outputPath, DataRow drw)
        {
            if (!File.Exists(templatePath))
                throw new FileNotFoundException("Không tìm thấy file PDF mẫu. Hãy xuất PDF từ file .repx và đặt tại Template/MauPDF.", templatePath);

            string strDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(strDir) && !Directory.Exists(strDir))
                Directory.CreateDirectory(strDir);

            PdfReader reader = null;
            FileStream fs = null;
            PdfStamper stamper = null;

            try
            {
                reader = new PdfReader(templatePath);
                fs = new FileStream(outputPath, FileMode.Create, FileAccess.Write);
                stamper = new PdfStamper(reader, fs);

                AcroFields form = stamper.AcroFields;
                bool bolHasAcroForm = form != null && form.Fields != null && form.Fields.Count > 0;

                if (bolHasAcroForm)
                    FillAcroFormFields(form, drw);
                else
                    DrawOverlayFields(stamper, reader, drw);

                stamper.FormFlattening = true;
            }
            finally
            {
                if (stamper != null)
                    stamper.Close();
                if (reader != null)
                    reader.Close();
                if (fs != null)
                    fs.Dispose();
            }
        }

        private static void FillAcroFormFields(AcroFields form, DataRow drw)
        {
            int i;
            for (i = 0; i < DetailFields.Length; i++)
            {
                PdfTextField item = DetailFields[i];
                if (string.IsNullOrEmpty(item.AcroFieldName))
                    continue;

                if (!form.Fields.ContainsKey(item.AcroFieldName))
                    continue;

                form.SetField(item.AcroFieldName, item.GetValue(drw));
            }
        }

        private static void DrawOverlayFields(PdfStamper stamper, PdfReader reader, DataRow drw)
        {
            BaseFont fontRegular = CreateUnicodeFont(false);
            BaseFont fontBold = CreateUnicodeFont(true);
            PdfContentByte canvas = stamper.GetOverContent(1);

            int i;
            for (i = 0; i < DetailFields.Length; i++)
            {
                PdfTextField item = DetailFields[i];
                string strValue = item.GetValue(drw);
                if (string.IsNullOrEmpty(strValue))
                    continue;

                BaseFont font = item.Bold ? fontBold : fontRegular;
                float x = ToPointX(item.X);
                float y = ToPointY(item.Y, item.Height);
                float fontSize = item.FontSize;

                ColumnText.ShowTextAligned(
                    canvas,
                    Element.ALIGN_LEFT,
                    new Phrase(strValue, new Font(font, fontSize)),
                    x,
                    y,
                    0);
            }
        }

        private static BaseFont CreateUnicodeFont(bool bold)
        {
            string strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "times.ttf");
            if (!File.Exists(strFontPath))
                strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "arial.ttf");

            if (!File.Exists(strFontPath))
                return BaseFont.CreateFont(BaseFont.HELVETICA, BaseFont.CP1252, BaseFont.NOT_EMBEDDED);

            return BaseFont.CreateFont(strFontPath, BaseFont.IDENTITY_H, BaseFont.EMBEDDED);
        }

        private static float ToPointX(float devExpressX)
        {
            return devExpressX / 100F * 72F;
        }

        private static float ToPointY(float devExpressY, float devExpressHeight)
        {
            return (PAGE_HEIGHT_DX - devExpressY - devExpressHeight) / 100F * 72F;
        }

        private static string GetRowValue(DataRow drw, string strColumnName)
        {
            if (drw == null || drw.Table == null || !drw.Table.Columns.Contains(strColumnName))
                return "";

            if (drw[strColumnName] == null || drw[strColumnName] == DBNull.Value)
                return "";

            return drw[strColumnName].ToString().Trim();
        }

        private static bool TryGetDate(DataRow drw, string strColumnName, out DateTime dtmValue)
        {
            dtmValue = DateTime.MinValue;
            string strValue = GetRowValue(drw, strColumnName);
            if (strValue == "")
                return false;

            return DateTime.TryParse(strValue, out dtmValue);
        }

        private static string GetStudentFullName(DataRow drw)
        {
            string strFullName = GetRowValue(drw, "StudentFullName");
            if (strFullName != "")
                return strFullName;

            strFullName = GetRowValue(drw, "Fullname");
            if (strFullName != "")
                return strFullName;

            return String.Format("{0} {1}", GetRowValue(drw, "StudentFirstName"), GetRowValue(drw, "StudentLastName")).Trim();
        }

        private static string GetBirthDateText(DataRow drw)
        {
            return GetRowValue(drw, "BirthDateText");
        }

        private static string GetSpecialBranchName(DataRow drw)
        {
            string strValue = GetRowValue(drw, "SpecialBranchName");
            if (strValue != "")
                return strValue;

            return GetRowValue(drw, "CourseName");
        }

        private static string GetStartAtDay(DataRow drw)
        {
            DateTime dtmValue;
            if (!TryGetDate(drw, "StartAt", out dtmValue))
                return "";
            return dtmValue.Day.ToString("00");
        }

        private static string GetStartAtMonth(DataRow drw)
        {
            DateTime dtmValue;
            if (!TryGetDate(drw, "StartAt", out dtmValue))
                return "";
            return dtmValue.Month.ToString("00");
        }

        private static string GetStartAtYear(DataRow drw)
        {
            DateTime dtmValue;
            if (!TryGetDate(drw, "StartAt", out dtmValue))
                return "";
            return dtmValue.Year.ToString();
        }

        private static string GetFinishAtDay(DataRow drw)
        {
            DateTime dtmValue;
            if (!TryGetDate(drw, "FinishAt", out dtmValue))
                return "";
            return dtmValue.Day.ToString("00");
        }

        private static string GetFinishAtMonth(DataRow drw)
        {
            DateTime dtmValue;
            if (!TryGetDate(drw, "FinishAt", out dtmValue))
                return "";
            return dtmValue.Month.ToString("00");
        }

        private static string GetFinishAtYear(DataRow drw)
        {
            DateTime dtmValue;
            if (!TryGetDate(drw, "FinishAt", out dtmValue))
                return "";
            return dtmValue.Year.ToString();
        }

        private static string GetGraduationLevel(DataRow drw)
        {
            return GetRowValue(drw, "GraduationLevel");
        }

        private static string GetCerNo(DataRow drw)
        {
            return GetRowValue(drw, "CerNo");
        }

        private static string GetSavedCerNo(DataRow drw)
        {
            return GetRowValue(drw, "SavedCerNo");
        }

        private static string GetCerIssuedSpaced(DataRow drw)
        {
            DateTime dtmValue;
            if (!TryGetDate(drw, "CerIssued", out dtmValue))
                return "";

            return String.Format("{0,2}              {1,2}             {2}",
                dtmValue.Day,
                dtmValue.Month,
                dtmValue.Year);
        }
    }
}

