        private bool OpenExportListInNewTab(string strHtml, string outputFileName, string outputPath)
        {
            string strPath = AppDomain.CurrentDomain.BaseDirectory;

            string strFileNameSaveAs = outputFileName;
            string strPathSaveAs = outputPath;
            if (outputPath == null)
                strPathSaveAs = strPath + "Export\\" + strFileNameSaveAs;

            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(strPathSaveAs));
                File.WriteAllText(strPathSaveAs, strHtml, Encoding.UTF8);
            }
            catch (Exception ex)
            {
                MsgBox.ShowError("Không thể tạo file HTML xuất. " + ex.Message);
                return false;
            }

            if (outputPath == null)
            {
                string strOutputPath_Pdf = Path.ChangeExtension(strPathSaveAs, "pdf");
                Libs.ChromePdfHelper.ConvertToPdf(strPathSaveAs, strOutputPath_Pdf, @"C:\Program Files\Google\Chrome\Application\chrome.exe");
                File.Delete(strPathSaveAs);

                string strUrl = "/Export/" + Path.ChangeExtension(strFileNameSaveAs, "pdf")
                    + "?time=" + DateTime.Now.ToString("yyMMddHHmmss");

                ScriptManager.RegisterStartupScript(Page, Page.GetType(), "_OpenListPdf",
                    String.Format("window.open('{0}','_blank');", strUrl), true);
            }

            return true;
        }

        private bool OpenExportDetailPdf(DataRow drw, string outputFileName)
