            {
                MsgBox.ShowError("Chưa có dữ liệu để xuất! Hãy thử tìm kiếm lại dữ liệu!");
                return;
            }

            if (dtbExport.Rows.Count == 0)
            {
                MsgBox.ShowWarning("Không có dữ liệu để xuất!");
                return;
            }

            LinkButton lbtExport = sender as LinkButton;
            int intGraduationResultID;
            if (!Int32.TryParse(lbtExport.CommandArgument, out intGraduationResultID))
            {
                MsgBox.ShowError("Không xác định được bản ghi cần xuất!");
                return;
            }

            int i = 0;
            for (i = 0; i < dtbExport.Rows.Count; i++)
            {
                if (Convert.ToInt32(dtbExport.Rows[i]["GraduationResultID"]) == intGraduationResultID)
                    break;
