public const string PDF_TEMPLATE_FILE = "Graduation_BangTotNghiep_SC2_1.pdf";

private const float PAGE_WIDTH_DX = 800F;
private const float PAGE_HEIGHT_DX = 780F;
private const float LABEL_PADDING_DX = 2F; // PaddingInfo(2,2,0,0,100F) trong repx

private static void DrawOverlayFields(PdfStamper stamper, DataRow drw)
{
    BaseFont fontRegular = CreateUnicodeFont(false);
    BaseFont fontBold = CreateUnicodeFont(true);
    PdfContentByte canvas = stamper.GetOverContent(1);

    int i;
    for (i = 0; i < DetailFields.Length; i++)
    {
        PdfTextField item = DetailFields[i];
        string strValue = item.GetValue(drw);
        if (string.IsNullOrEmpty(strValue))
            continue;

        BaseFont font = item.Bold ? fontBold : fontRegular;
        Font pdfFont = new Font(font, item.FontSize);
        Rectangle rect = GetLabelRectangle(item);

        ColumnText columnText = new ColumnText(canvas);
        columnText.SetSimpleColumn(
            new Phrase(strValue, pdfFont),
            rect.Left,
            rect.Bottom,
            rect.Right,
            rect.Top,
            item.FontSize,
            Element.ALIGN_LEFT);
        columnText.Go();
    }
}

/// <summary>
/// Chuyển khung XRLabel (repx) sang Rectangle iTextSharp (gốc dưới-trái, đơn vị point).
/// </summary>
private static Rectangle GetLabelRectangle(PdfTextField item)
{
    float left = ToPointX(item.X + LABEL_PADDING_DX);
    float right = ToPointX(item.X + item.Width);
    float top = ToPointY(item.Y);
    float bottom = ToPointY(item.Y + item.Height);

    return new Rectangle(left, bottom, right, top);
}

