using System;
using System.Data;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;

namespace InformationWeb.Controls.Graduation
{
    /// <summary>
    /// Điền dữ liệu chi tiết văn bằng lên PDF phôi (iTextSharp).
  /// PDF mẫu: Template/MauPDF/{PDF_TEMPLATE_FILE} — xuất từ file .repx tương ứng.
    /// </summary>
    public static class GraduationBangTotNghiepPdfFiller
    {
        #region Cấu hình mẫu — ĐỔI KHI DÙNG REPX / PHÔI KHÁC

        /// <summary>Tên file PDF phôi trong Template/MauPDF/</summary>
        public const string PDF_TEMPLATE_FILE = "Graduation_BangTotNghiep_SC2_1.pdf";

        /// <summary>Khổ trang repx: PageWidth, PageHeight (đơn vị 1/100 inch)</summary>
        private const float PAGE_HEIGHT_DX = 780F;

        /// <summary>Padding XRLabel trong repx: PaddingInfo(2,2,0,0,100F)</summary>
        private const float LABEL_PADDING_DX = 2F;

        /// <summary>
        /// Map field: tên AcroForm (nếu PDF có field) + tọa độ repx + cách lấy data.
        /// Đổi mẫu phôi mới: sửa X,Y,Width,Height,FontSize,Bold theo LocationFloat/SizeF trong .repx.
        /// PDF có AcroForm → SetField theo AcroFieldName; không có → in chữ đè theo tọa độ.
        /// </summary>
        private static readonly PdfTextField[] DetailFields = new PdfTextField[]
        {
            // label9 — Table.StudentFullName
            Field("StudentFullName", 176.8336F, 295.5416F, 549.4995F, 25F, true, GetStudentFullName),
            // label25 — Table.BirthDateText
            Field("BirthDateText", 176.8336F, 337.2083F, 549.4996F, 25F, false, GetBirthDateText),
            // label3 — Table.SpecialBranchName
            Field("SpecialBranchName", 288.9999F, 377.6669F, 437.3332F, 24.04169F, false, GetSpecialBranchName),
            // label1, label13, label8 — Table.StartAt
            Field("StartAt_Day", 127.0834F, 419.25F, 57.04161F, 25F, false, delegate(DataRow drw) { return GetDatePart(drw, "StartAt", "dd"); }),
            Field("StartAt_Month", 233.0833F, 419.25F, 47.66661F, 25F, false, delegate(DataRow drw) { return GetDatePart(drw, "StartAt", "MM"); }),
            Field("StartAt_Year", 316.1666F, 419.3334F, 62.24994F, 25F, false, delegate(DataRow drw) { return GetDatePart(drw, "StartAt", "yyyy"); }),
            // label2, label10, label11 — Table.FinishAt
            Field("FinishAt_Day", 462.6669F, 419.0833F, 46.62491F, 25F, false, delegate(DataRow drw) { return GetDatePart(drw, "FinishAt", "dd"); }),
            Field("FinishAt_Month", 559.2917F, 419.3334F, 41.4166F, 25F, false, delegate(DataRow drw) { return GetDatePart(drw, "FinishAt", "MM"); }),
            Field("FinishAt_Year", 646.5418F, 419.0833F, 79.79126F, 25F, false, delegate(DataRow drw) { return GetDatePart(drw, "FinishAt", "yyyy"); }),
            // label6 — Table.GraduationLevel
            Field("GraduationLevel", 175.5417F, 461.9999F, 550.7913F, 25F, false, delegate(DataRow drw) { return GetRowValue(drw, "GraduationLevel"); }),
            // label12 — pCerIssued
            Field("CerIssued", 490.7918F, 498.5835F, 235.5413F, 25.00003F, false, GetCerIssuedSpaced),
