            // label16 — Table.SavedCerNo
            Field("SavedCerNo", 233.0831F, 635.4582F, 493.2499F, 24.04163F, false, delegate(DataRow drw) { return GetRowValue(drw, "SavedCerNo"); })
        };

        #endregion

        #region Xuất PDF

        public static void FillDetailPdf(string templatePath, string outputPath, DataRow drw)
        {
            if (!File.Exists(templatePath))
            {
                throw new FileNotFoundException(
                    String.Format("Không tìm thấy PDF mẫu: {0}. Đặt file tại Template/MauPDF/.", templatePath),
                    templatePath);
            }

            string strDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(strDir) && !Directory.Exists(strDir))
                Directory.CreateDirectory(strDir);

            PdfReader reader = null;
            FileStream fs = null;
            PdfStamper stamper = null;

            try
            {
                reader = new PdfReader(templatePath);
                fs = new FileStream(outputPath, FileMode.Create, FileAccess.Write);
                stamper = new PdfStamper(reader, fs);

                AcroFields form = stamper.AcroFields;
                if (form != null && form.Fields != null && form.Fields.Count > 0)
                    FillAcroForm(form, drw);       // PDF mẫu kiểu cũ: có Text Field sẵn
                else
                    DrawOverlay(stamper, drw);     // PDF phôi repx: in chữ theo tọa độ

                stamper.FormFlattening = true;      // cố định text trước khi ký số
            }
            finally
            {
                if (stamper != null) stamper.Close();
                if (reader != null) reader.Close();
                if (fs != null) fs.Dispose();
            }
        }

        private static void FillAcroForm(AcroFields form, DataRow drw)
        {
            int i;
            for (i = 0; i < DetailFields.Length; i++)
            {
                PdfTextField item = DetailFields[i];
                if (string.IsNullOrEmpty(item.AcroFieldName))
                    continue;
                if (!form.Fields.ContainsKey(item.AcroFieldName))
                    continue;

                form.SetField(item.AcroFieldName, item.GetValue(drw));
            }
        }

        private static void DrawOverlay(PdfStamper stamper, DataRow drw)
        {
            BaseFont fontRegular = CreateUnicodeFont(false);
            BaseFont fontBold = CreateUnicodeFont(true);
            PdfContentByte canvas = stamper.GetOverContent(1);

            int i;
            for (i = 0; i < DetailFields.Length; i++)
            {
                PdfTextField item = DetailFields[i];
                string strValue = item.GetValue(drw);
                if (string.IsNullOrEmpty(strValue))
                    continue;

                BaseFont baseFont = item.Bold ? fontBold : fontRegular;
                Rectangle rect = ToLabelRect(item);
                ColumnText ct = new ColumnText(canvas);

                ct.SetSimpleColumn(
                    new Phrase(strValue, new Font(baseFont, item.FontSize)),
                    rect.Left, rect.Bottom, rect.Right, rect.Top,
                    item.FontSize, Element.ALIGN_LEFT);
                ct.Go();
            }
        }

        #endregion

        #region Chuyển tọa độ repx → iTextSharp

        private static Rectangle ToLabelRect(PdfTextField item)
        {
            return new Rectangle(
                ToPointX(item.X + LABEL_PADDING_DX),
                ToPointY(item.Y + item.Height),
                ToPointX(item.X + item.Width),
                ToPointY(item.Y));
        }

        private static float ToPointX(float devExpressX)
        {
            return devExpressX / 100F * 72F;
        }

        private static float ToPointY(float devExpressY)
        {
            return (PAGE_HEIGHT_DX - devExpressY) / 100F * 72F;
        }

        private static BaseFont CreateUnicodeFont(bool bold)
        {
            string strFontFile = bold ? "timesbd.ttf" : "times.ttf";
            string strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), strFontFile);
            if (!File.Exists(strFontPath))
                strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "arial.ttf");
            if (!File.Exists(strFontPath))
                return BaseFont.CreateFont(BaseFont.HELVETICA, BaseFont.CP1252, BaseFont.NOT_EMBEDDED);

            return BaseFont.CreateFont(strFontPath, BaseFont.IDENTITY_H, BaseFont.EMBEDDED);
        }

        #endregion

        #region Lấy dữ liệu từ DataRow — sửa nếu SP đổi tên cột

        private static string GetStudentFullName(DataRow drw)
        {
            string str = GetRowValue(drw, "StudentFullName");
            if (str != "") return str;

            str = GetRowValue(drw, "Fullname");
            if (str != "") return str;

            return String.Format("{0} {1}", GetRowValue(drw, "StudentFirstName"), GetRowValue(drw, "StudentLastName")).Trim();
        }

        private static string GetBirthDateText(DataRow drw)
        {
            return GetRowValue(drw, "BirthDateText");
        }

        private static string GetSpecialBranchName(DataRow drw)
        {
            string str = GetRowValue(drw, "SpecialBranchName");
            return str != "" ? str : GetRowValue(drw, "CourseName");
        }

        private static string GetCerIssuedSpaced(DataRow drw)
        {
            DateTime dtm;
            if (!TryGetDate(drw, "CerIssued", out dtm) && !TryGetDate(drw, "pCerIssued", out dtm))
                return "";

            // format repx label12: {0:dd              MM             yyyy}
            return dtm.ToString("dd              MM             yyyy");
        }

        private static string GetDatePart(DataRow drw, string strColumn, string strFormat)
        {
            DateTime dtm;
            if (!TryGetDate(drw, strColumn, out dtm))
                return "";
            return dtm.ToString(strFormat);
        }

        private static string GetRowValue(DataRow drw, string strColumnName)
        {
            if (drw == null || drw.Table == null || !drw.Table.Columns.Contains(strColumnName))
                return "";
            if (drw[strColumnName] == null || drw[strColumnName] == DBNull.Value)
                return "";
            return drw[strColumnName].ToString().Trim();
        }

        private static bool TryGetDate(DataRow drw, string strColumnName, out DateTime dtmValue)
        {
            dtmValue = DateTime.MinValue;
            string strValue = GetRowValue(drw, strColumnName);
            if (strValue == "")
                return false;
            return DateTime.TryParse(strValue, out dtmValue);
        }

        #endregion

        #region Helper khai báo field

        private delegate string GetFieldValueHandler(DataRow drw);

        private sealed class PdfTextField
        {
            public string AcroFieldName;
            public float X;
            public float Y;
            public float Width;
            public float Height;
            public float FontSize;
            public bool Bold;
            public GetFieldValueHandler GetValue;
        }

        private static PdfTextField Field(string acroName, float x, float y, float w, float h, bool bold, GetFieldValueHandler getValue)
        {
            PdfTextField item = new PdfTextField();
            item.AcroFieldName = acroName;
            item.X = x;
            item.Y = y;
            item.Width = w;
            item.Height = h;
            item.FontSize = 14F;   // repx: Times New Roman 14F — đổi nếu mẫu khác cỡ chữ
            item.Bold = bold;
            item.GetValue = getValue;
            return item;
        }

        #endregion
    }
}

