using iTextSharp.text.pdf;

namespace InformationWeb.Controls.Graduation
{
    /// <summary>
    /// Điền dữ liệu chi tiết văn bằng lên PDF phôi (iTextSharp).
    /// PDF mẫu: Template/MauPDF/{PDF_TEMPLATE_FILE} — xuất từ file .repx tương ứng.
    /// Tọa độ khung/vị trí: copy nguyên LocationFloat + SizeF từ .repx, cộng margin trang khi in đè.
    /// </summary>
    public static class GraduationBangTotNghiepPdfFiller
    {
        #region Cấu hình mẫu — ĐỔI KHI DÙNG REPX / PHÔI KHÁC

        /// <summary>Tên file PDF phôi trong Template/MauPDF/</summary>
        public const string PDF_TEMPLATE_FILE = "Graduation_BangTotNghiep_SC2_2.pdf";

        /// <summary>repx SC2_2: PageWidth x PageHeight, Landscape A5 (đơn vị 1/100 inch)</summary>
        private const float PAGE_WIDTH_DX = 827F;
        private const float PAGE_HEIGHT_DX = 583F;

        /// <summary>repx SC2_2: Margins = new Margins(25, 5, 1, 1)</summary>
        private const float REPX_MARGIN_LEFT = 25F;
        private const float REPX_MARGIN_TOP = 1F;

        /// <summary>repx XRLabel: PaddingInfo(2, 2, 0, 0, 100F)</summary>
        private const float REPX_LABEL_PADDING_LEFT = 2F;
        private const float REPX_LABEL_PADDING_RIGHT = 2F;

        /// <summary>
        /// Khung từng field — X,Y,Width,Height = LocationFloat + SizeF trong Graduation_BangTotNghiep_SC2_2.repx (PageHeader).
        /// FontSize = Font.Size trong repx. Bold = StylePriority.UseFont + Times New Roman Bold (label9).
        /// </summary>
        private static readonly PdfTextField[] DetailFields = new PdfTextField[]
        {
            // label9 — Table.StudentFullName
            Field("StudentFullName", 232.7083F, 240.8749F, 335.7914F, 24.99998F, 13F, true, GetStudentFullName),
            // label25 — Table.BirthDateText
            Field("BirthDateText", 647.0836F, 241.8749F, 142.208F, 25.00002F, 13F, false, GetBirthDateText),
            // label3 — Table.PersonID
            Field("PersonID", 243.7083F, 277.1667F, 397.9167F, 23F, 13F, false, GetPersonID),
            // label1 — Table.SpecialBranchShortName
            Field("SpecialBranchShortName", 501.4582F, 309.25F, 287.8333F, 23F, 13F, false, GetSpecialBranchShortName),
            // label2 — Table.DayOfCourse
            Field("DayOfCourse", 213.7503F, 339.3334F, 83.33331F, 23F, 13F, false, GetDayOfCourse),
            // label8 — Table.StartAt {0:dd/MM/yyyy}
            Field("StartAt", 383.8751F, 337.3334F, 105.9999F, 25F, 13F, false, GetStartAtText),
            // label11 — Table.FinishAt {0:dd/MM/yyyy}
            Field("FinishAt", 573.9167F, 337.3334F, 113.1246F, 25F, 13F, false, GetFinishAtText),
            // label4 — Table.CerNo
            Field("CerNo", 289.0419F, 178.875F, 327.2498F, 22.99998F, 13F, false, GetCerNo),
            // label6 — Table.Signingdate {0:dd}
            Field("Signingdate_Day", 530.875F, 391.75F, 43.75F, 25.00009F, 13F, false, delegate(DataRow drw) { return GetDatePart(drw, "Signingdate", "dd"); }),
            // label7 — Table.Signingdate {0:MM}
            Field("Signingdate_Month", 606.1666F, 391.75F, 43.75F, 25.00009F, 13F, false, delegate(DataRow drw) { return GetDatePart(drw, "Signingdate", "MM"); }),
            // label10 — Table.Signingdate {0:yyyy}
            Field("Signingdate_Year", 668.4999F, 391.7499F, 88.20819F, 25F, 13F, false, delegate(DataRow drw) { return GetDatePart(drw, "Signingdate", "yyyy"); })
        };

        #endregion

        #region Xuất PDF

        public static void FillDetailPdf(string templatePath, string outputPath, DataRow drw)
        {
            if (!File.Exists(templatePath))
            {
                throw new FileNotFoundException(
                    String.Format("Không tìm thấy PDF mẫu: {0}. Đặt file tại Template/MauPDF/.", templatePath),
                    templatePath);
            }

            string strDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(strDir) && !Directory.Exists(strDir))
                Directory.CreateDirectory(strDir);

            PdfReader reader = null;
            FileStream fs = null;
            PdfStamper stamper = null;

            try
            {
                reader = new PdfReader(templatePath);
                fs = new FileStream(outputPath, FileMode.Create, FileAccess.Write);
                stamper = new PdfStamper(reader, fs);

                AcroFields form = stamper.AcroFields;
                if (form != null && form.Fields != null && form.Fields.Count > 0)
                    FillAcroForm(form, drw);
                else
                    DrawOverlay(stamper, reader, drw);

                stamper.FormFlattening = true;
            }
            finally
            {
                if (stamper != null) stamper.Close();
                if (reader != null) reader.Close();
                if (fs != null) fs.Dispose();
            }
        }

        private static void FillAcroForm(AcroFields form, DataRow drw)
        {
            int i;
            for (i = 0; i < DetailFields.Length; i++)
            {
                PdfTextField item = DetailFields[i];
                if (string.IsNullOrEmpty(item.AcroFieldName))
                    continue;
                if (!form.Fields.ContainsKey(item.AcroFieldName))
                    continue;

                form.SetField(item.AcroFieldName, item.GetValue(drw));
            }
        }

        private static void DrawOverlay(PdfStamper stamper, PdfReader reader, DataRow drw)
        {
            BaseFont fontRegular = CreateUnicodeFont(false);
            BaseFont fontBold = CreateUnicodeFont(true);
            PdfContentByte canvas = stamper.GetOverContent(1);
            Rectangle pageSize = reader.GetPageSizeWithRotation(1);

            int i;
            for (i = 0; i < DetailFields.Length; i++)
            {
                PdfTextField item = DetailFields[i];
                string strValue = item.GetValue(drw);
                if (string.IsNullOrEmpty(strValue))
                    continue;

                BaseFont baseFont = item.Bold ? fontBold : fontRegular;
                Rectangle rect = ToLabelRect(item, pageSize);
                ColumnText ct = new ColumnText(canvas);

                ct.SetSimpleColumn(
                    new Phrase(strValue, new Font(baseFont, item.FontSize)),
                    rect.Left, rect.Bottom, rect.Right, rect.Top,
                    item.FontSize, Element.ALIGN_LEFT);
                ct.Go();
            }
        }

        #endregion

        #region Chuyển tọa độ repx → iTextSharp

        /// <summary>
        /// DevExpress: gốc trên-trái, đơn vị 1/100 inch.
        /// iText: gốc dưới-trái, đơn vị point.
        /// Vị trí tuyệt đối trên trang = margin trang + LocationFloat (band PageHeader).
        /// </summary>
        private static Rectangle ToLabelRect(PdfTextField item, Rectangle pageSize)
        {
            float pageWidthPt = pageSize.Width;
            float pageHeightPt = pageSize.Height;
            float expectedWidthPt = PAGE_WIDTH_DX / 100F * 72F;
            float expectedHeightPt = PAGE_HEIGHT_DX / 100F * 72F;
            float scaleX = pageWidthPt / expectedWidthPt;
            float scaleY = pageHeightPt / expectedHeightPt;

            float absX = REPX_MARGIN_LEFT + item.X;
            float absY = REPX_MARGIN_TOP + item.Y;

            float leftDx = absX + REPX_LABEL_PADDING_LEFT;
            float rightDx = absX + item.Width - REPX_LABEL_PADDING_RIGHT;
            float topDx = absY;
            float bottomDx = absY + item.Height;

            float left = DxToPoint(leftDx, scaleX);
            float right = DxToPoint(rightDx, scaleX);
            float top = pageHeightPt - DxToPoint(topDx, scaleY);
            float bottom = pageHeightPt - DxToPoint(bottomDx, scaleY);

            return new Rectangle(left, bottom, right, top);
        }

        private static float DxToPoint(float valueDx, float scale)
        {
            return valueDx / 100F * 72F * scale;
        }

        private static BaseFont CreateUnicodeFont(bool bold)
        {
            string strFontFile = bold ? "timesbd.ttf" : "times.ttf";
            string strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), strFontFile);
            if (!File.Exists(strFontPath))
                strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "arial.ttf");
            if (!File.Exists(strFontPath))
                return BaseFont.CreateFont(BaseFont.HELVETICA, BaseFont.CP1252, BaseFont.NOT_EMBEDDED);

            return BaseFont.CreateFont(strFontPath, BaseFont.IDENTITY_H, BaseFont.EMBEDDED);
        }

        #endregion

        #region Lấy dữ liệu từ DataRow — sửa nếu SP đổi tên cột

        private static string GetStudentFullName(DataRow drw)
        {
            string str = GetRowValue(drw, "StudentFullName");
            if (str != "") return str;

            str = GetRowValue(drw, "Fullname");
            if (str != "") return str;

            return String.Format("{0} {1}", GetRowValue(drw, "StudentFirstName"), GetRowValue(drw, "StudentLastName")).Trim();
        }

        private static string GetBirthDateText(DataRow drw)
        {
            return GetRowValue(drw, "BirthDateText");
        }

        private static string GetPersonID(DataRow drw)
        {
            return GetRowValue(drw, "PersonID");
        }

        private static string GetSpecialBranchShortName(DataRow drw)
        {
            string str = GetRowValue(drw, "SpecialBranchShortName");
            if (str != "") return str;

            return GetRowValue(drw, "SpecialBranchName");
        }

        private static string GetDayOfCourse(DataRow drw)
        {
            return GetRowValue(drw, "DayOfCourse");
        }

        private static string GetCerNo(DataRow drw)
        {
            return GetRowValue(drw, "CerNo");
        }

        private static string GetStartAtText(DataRow drw)
        {
            return GetDateText(drw, "StartAt", "dd/MM/yyyy");
        }

        private static string GetFinishAtText(DataRow drw)
        {
            return GetDateText(drw, "FinishAt", "dd/MM/yyyy");
        }

        private static string GetDateText(DataRow drw, string strColumn, string strFormat)
        {
            DateTime dtm;
            if (!TryGetDate(drw, strColumn, out dtm))
                return "";
            return dtm.ToString(strFormat);
        }

        private static string GetDatePart(DataRow drw, string strColumn, string strFormat)
        {
            DateTime dtm;
            if (!TryGetDate(drw, strColumn, out dtm))
                return "";
            return dtm.ToString(strFormat);
        }

        private static string GetRowValue(DataRow drw, string strColumnName)
        {
            if (drw == null || drw.Table == null || !drw.Table.Columns.Contains(strColumnName))
                return "";
            if (drw[strColumnName] == null || drw[strColumnName] == DBNull.Value)
                return "";
            return drw[strColumnName].ToString().Trim();
        }

        private static bool TryGetDate(DataRow drw, string strColumnName, out DateTime dtmValue)
        {
            dtmValue = DateTime.MinValue;
            string strValue = GetRowValue(drw, strColumnName);
            if (strValue == "")
                return false;
            return DateTime.TryParse(strValue, out dtmValue);
        }

        #endregion

        #region Helper khai báo field

        private delegate string GetFieldValueHandler(DataRow drw);

        private sealed class PdfTextField
        {
            public string AcroFieldName;
            public float X;
            public float Y;
            public float Width;
            public float Height;
            public float FontSize;
            public bool Bold;
            public GetFieldValueHandler GetValue;
        }

        private static PdfTextField Field(string acroName, float x, float y, float w, float h, float fontSize, bool bold, GetFieldValueHandler getValue)
        {
            PdfTextField item = new PdfTextField();
            item.AcroFieldName = acroName;
            item.X = x;
            item.Y = y;
            item.Width = w;
            item.Height = h;
            item.FontSize = fontSize;
            item.Bold = bold;
            item.GetValue = getValue;
            return item;
        }

        #endregion
    }
}

