private static void DrawOverlay(PdfStamper stamper, PdfReader reader, DataRow drw)
{
    BaseFont fontRegular = CreateUnicodeFont(false);
    BaseFont fontBold = CreateUnicodeFont(true);
    PdfContentByte canvas = stamper.GetOverContent(1);
    Rectangle pageSize = reader.GetPageSizeWithRotation(1);

    if (DRAW_STATIC_LABELS)
    {
        int j;
        for (j = 0; j < StaticFields.Length; j++)
        {
            PdfStaticField staticItem = StaticFields[j];
            DrawTextInRect(canvas, pageSize, staticItem.Text, staticItem.X, staticItem.Y,
                staticItem.Width, staticItem.Height, staticItem.FontSize, staticItem.Bold, fontRegular, fontBold);
        }
    }

    int i;
    for (i = 0; i < DetailFields.Length; i++)
    {
        PdfTextField item = DetailFields[i];
        string strValue = item.GetValue(drw);
        if (string.IsNullOrEmpty(strValue))
            continue;

        DrawTextInRect(canvas, pageSize, strValue, item.X, item.Y, item.Width, item.Height,
            item.FontSize, item.Bold, fontRegular, fontBold);
    }
}

private static void DrawTextInRect(PdfContentByte canvas, Rectangle pageSize, string strValue,
    float x, float y, float width, float height, float fontSize, bool bold,
    BaseFont fontRegular, BaseFont fontBold)
{
    BaseFont baseFont = bold ? fontBold : fontRegular;
    Rectangle rect = ToLabelRect(x, y, width, height, pageSize);
    ColumnText ct = new ColumnText(canvas);

    ct.SetSimpleColumn(
        new Phrase(strValue, new Font(baseFont, fontSize)),
        rect.Left, rect.Bottom, rect.Right, rect.Top,
        fontSize, Element.ALIGN_LEFT);
    ct.Go();
}

